    @_retry_on_busy
    def reap_stale_work(self, timeout_seconds: float = STALE_TIMEOUT_SECONDS) -> dict:
        """Reap zombie work items and help requests that have been stuck.

        Finds work items in 'in_progress' and help requests in 'accepted'
        whose updated_at/created_at is older than timeout_seconds. Resets
        them to 'available_for_help'/'open' so they can be reassigned.

        Returns dict with 'work_items_reaped' and 'requests_reopened' counts.
        """
        now = time.time()
        cutoff = now - timeout_seconds
        reaped_work = 0
        reopened_requests = 0

        with self._lock:
            self._check_closed()
            try:
                self._conn.execute("BEGIN IMMEDIATE")
            except sqlite3.OperationalError:
                raise

            try:
                # Find stale in_progress work items
                stale_items = self._conn.execute(
                    "SELECT id FROM work_items WHERE status = 'in_progress' AND updated_at < ?",
                    (cutoff,),
                ).fetchall()

                for item in stale_items:
                    self._conn.execute(
                        "UPDATE work_items SET status = 'available_for_help', assigned_to = NULL, updated_at = ? WHERE id = ?",
                        (now, item["id"]),
                    )
                    reaped_work += 1

                # Find stale accepted help requests
                stale_requests = self._conn.execute(
                    "SELECT id, work_item_id FROM help_requests WHERE status = 'accepted' AND resolved_at IS NULL",
                    (),
                ).fetchall()

                for req in stale_requests:
                    # Check if the accepted_by_team's last update is stale
                    self._conn.execute(
                        "UPDATE help_requests SET status = 'open', accepted_by_team = NULL, accepted_by_agent = NULL WHERE id = ?",
                        (req["id"],),
                    )
                    reopened_requests += 1

                self._conn.execute("COMMIT")

            except Exception:
                try:
                    self._conn.execute("ROLLBACK")
                except sqlite3.OperationalError:
                    pass
                raise

        if reaped_work > 0 or reopened_requests > 0:
            self._publish_bus("global", "info", {
                "event": "reaper-run",
                "work_items_reaped": reaped_work,
                "requests_reopened": reopened_requests,
                "timeout_seconds": timeout_seconds,
            })

        return {"work_items_reaped": reaped_work, "requests_reopened": reopened_requests}

