def _retry_on_busy(func):
    """Decorator: retry a method on SQLITE_BUSY / SQLITE_LOCKED errors."""
    def wrapper(*args, **kwargs):
        delay = _RETRY_BACKOFF
        last_err = None
        for attempt in range(_MAX_RETRIES):
            try:
                return func(*args, **kwargs)
            except sqlite3.OperationalError as e:
                if _is_busy_or_locked(e):
                    last_err = e
                    logger.debug(
                        "SQLITE_BUSY on %s (attempt %d/%d), retrying in %.2fs",
                        func.__name__, attempt + 1, _MAX_RETRIES, delay,
                    )
                    time.sleep(delay)
                    delay *= 2
                else:
                    raise
        raise last_err  # type: ignore[misc]
    return wrapper


def _is_busy_or_locked(exc: sqlite3.OperationalError) -> bool:
    """Check if a sqlite3 error is SQLITE_BUSY or SQLITE_LOCKED.

    Uses sqlite_errorcode attribute (Python 3.11+) when available,
    falls back to string matching for older versions.
    """
    # SQLITE_BUSY = 5, SQLITE_LOCKED = 6
    error_code = getattr(exc, "sqlite_errorcode", None)
    if error_code is not None:
        return error_code in (5, 6)
    # Fallback for Python < 3.11
    msg = str(exc).lower()
    return "locked" in msg or "busy" in msg
